/bin/bash -lc "PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=lib python - <<'PY'
from ansible.playbook.play import Play
from ansible.errors import AnsibleParserError
for hosts in (['ok', {'bad': 'value'}], [], None, ['ok', None], {'bad': 'value'}):
    try:
        p = Play.load({'hosts': hosts})
        print(repr(hosts), '=>', repr(p.get_name()))
    except Exception as e:
        print(repr(hosts), '=>', type(e).__name__, str(e).splitlines()[0])
PY"

